mapper.select:
select t.team_id, t.team_name, t.team_key, t.team_icon, t.create_by, t.create_time, t.update_by, t.update_time, t.introduce, t.is_del, t.is_lock, t.lock_remark, IFNULL(p.project_count, 0) as project_count, IFNULL(m.member_count, 0) as member_count from sys_team t LEFT JOIN ( select count(team_id) as project_count, team_id from sys_project group by team_id ) p ON p.team_id = t.team_id LEFT JOIN ( select count(team_id) as member_count, team_id from sys_user_team where team_lock = 0 group by team_id ) m ON m.team_id = t.team_id
and t.team_name like concat('%', #{teamName}, '%')
order by t.team_id limit #{limit} offset #{offset}

mapper.update:
update sys_team
team_name = #{teamName}, team_key = #{teamKey}, team_icon = #{teamIcon}, update_by = #{updateBy}, update_time = #{updateTime}, introduce = #{introduce}, is_lock = #{lock}, lock_remark = #{lockRemark},
where team_id = #{teamId}

mapper.select:
select user_team_id
from sys_user_team
where user_id = #{userId}
  and team_id = #{teamId}
order by user_team_id desc
limit 1
